/**
 * Seed FloorPlanPreset records with pre-populated objects for common wedding space types.
 * These presets provide the default furniture layout that the AI blocking pipeline uses
 * as spatial context. Cameras and subjects are NOT seeded here — they are created
 * dynamically by syncCamerasAndSubjects() from crew/subject assignments.
 * Zones are NOT seeded here — they are generated by Gemma AI from the object layout
 * via generateZonesFromObjects() on first spatial context build.
 *
 * Run order: After service scaffolding so seeded package sets and floor plan presets are available together.
 */
import { PrismaClient, FloorPlanObjectType, SpaceType } from '@prisma/client';
import { createSeedLogger, SeedType, type SeedSummary } from '../utils/seed-logger';

const prisma = new PrismaClient();
const logger = createSeedLogger(SeedType.MOONRISE);

// ── Canvas dimensions (all presets use 1000×1000 normalised canvas) ──
const W = 1000;
const H = 1000;

// ── Type aliases for readability ──
type ObjDef = {
  object_type: FloorPlanObjectType;
  label: string;
  x: number; y: number;
  width: number; height: number;
  rotation?: number;
  order_index: number;
};

interface PresetDef {
  name: string;
  description: string;
  space_type: SpaceType;
  guest_capacity: number | null;
  objects: ObjDef[];
}

