// ══════════════════════════════════════════════════════════════════════════════
// SEED FUNCTION
// ══════════════════════════════════════════════════════════════════════════════

export default async function seedFloorPlanPresets(): Promise<SeedSummary> {
  logger.sectionHeader('Floor Plan Presets');

  let created = 0;
  let skipped = 0;

  for (const def of ALL_PRESETS) {
    const existing = await prisma.floorPlanPreset.findFirst({
      where: { brand_id: null, name: def.name },
    });
    if (existing) {
      skipped++;
      logger.skipped(def.name);
      continue;
    }

    await prisma.floorPlanPreset.create({
      data: {
        brand_id: null,
        name: def.name,
        description: def.description,
        space_type: def.space_type,
        guest_capacity: def.guest_capacity,
        canvas_width: W,
        canvas_height: H,
        is_system_seeded: true,
        objects: {
          create: def.objects.map((o) => ({
            object_type: o.object_type,
            label: o.label,
            x: o.x,
            y: o.y,
            width: o.width,
            height: o.height,
            rotation: o.rotation ?? 0,
            order_index: o.order_index,
          })),
        },
      },
    });

    logger.created(`${def.name} (${def.objects.length} objects)`);
    created++;
  }

  return { created, updated: 0, skipped, total: ALL_PRESETS.length };
}
